  INDEX `IDX_LIKE_TARGET`(`TARGET_TYPE` ASC, `TARGET_ID` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户喜欢/点赞记录' ROW_FORMAT = DYNAMIC;

